const invoiceLines = [
  "INVOICE NUMBER: INV-PDF-2026-904",
  "DATE: 2026-10-14",
  "VENDOR: Acme Industrial Automation Corp",
  "ITEM: Industrial Sensor Pack x3 @ 150.00 USD = 450.00 USD",
  "ITEM: DIN Rail Power Supply x2 @ 85.50 USD = 171.00 USD",
  "SUBTOTAL: 621.00 USD",
  "TAX: 49.68 USD",
  "TOTAL: 670.68 USD"
];

const escapePdfText = (text) =>
  text.replace(/\\/g, "\\\\")
      .replace(/\(/g, "\\(")
      .replace(/\)/g, "\\)");

const textCommands = [
  "BT",
  "/F1 11 Tf",
  "50 750 Td",
  ...invoiceLines.flatMap((line, index) => [
    ...(index === 0 ? [] : ["0 -24 Td"]),
    `(${escapePdfText(line)}) Tj`
  ]),
  "ET"
].join("\n");

const stream = textCommands + "\n";

const objects = [
  "<< /Type /Catalog /Pages 2 0 R >>",
  "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
  "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>",
  `<< /Length ${Buffer.byteLength(stream, "utf8")} >>\nstream\n${stream}endstream`,
  "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>"
];

let pdf = "%PDF-1.4\n";
const offsets = [0];

for (let i = 0; i < objects.length; i++) {
  offsets.push(Buffer.byteLength(pdf, "utf8"));
  pdf += `${i + 1} 0 obj\n${objects[i]}\nendobj\n`;
}

const xrefOffset = Buffer.byteLength(pdf, "utf8");

pdf += `xref\n0 ${objects.length + 1}\n`;
pdf += "0000000000 65535 f \n";

for (let i = 1; i < offsets.length; i++) {
  pdf += `${String(offsets[i]).padStart(10, "0")} 00000 n \n`;
}

pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\n`;
pdf += `startxref\n${xrefOffset}\n%%EOF`;

const base64Data = Buffer.from(pdf, "utf8").toString("base64");

return [
  {
    json: {
      fileName: "vendor_invoice_INV-904.pdf",
      sourceChannel: "Supplier_Portal_Upload",
      fileType: "application/pdf"
    },
    binary: {
      data: {
        data: base64Data,
        mimeType: "application/pdf",
        fileName: "vendor_invoice_INV-904.pdf",
        fileExtension: "pdf"
      }
    }
  }
];

const rawText = $input.item.json.text || "";

const extract = (regex) => {
  const match = rawText.match(regex);
  return match ? match[1].trim() : null;
};

const invoiceNumber = extract(
  /INVOICE NUMBER:\s*([A-Z0-9-]+)/i
);

const invoiceDate = extract(
  /DATE:\s*(\d{4}-\d{2}-\d{2})/i
);

const vendor = extract(
  /VENDOR:\s*([^\r\n]+)/i
);

const subtotal = extract(
  /SUBTOTAL:\s*([\d,]+(?:\.\d{1,2})?)/i
);

const tax = extract(
  /TAX:\s*([\d,]+(?:\.\d{1,2})?)/i
);

const total = extract(
  /TOTAL:\s*([\d,]+(?:\.\d{1,2})?)/i
);

const itemRegex =
  /ITEM:\s*(.*?)\s+x(\d+)\s+@\s*([\d.]+)\s+USD\s*=\s*([\d.]+)\s+USD/gi;

const items = [];
let match;

while ((match = itemRegex.exec(rawText)) !== null) {
  items.push({
    sku: "PDF-EXTRACTED-SKU",
    description: match[1].trim(),
    quantity: Number(match[2]),
    unitPrice: Number(match[3]),
    lineTotal: Number(match[4])
  });
}

if (!invoiceNumber || !invoiceDate || !vendor ||
    subtotal === null || tax === null || total === null ||
    items.length === 0) {
  throw new Error(
    "Invoice parsing failed. Check the extracted PDF text."
  );
}

return {
  json: {
    sourceType: "PDF_INVOICE",
    orderId: invoiceNumber,
    orderDate: invoiceDate,
    customer: {
      fullName: vendor,
      email: "billing@acmeindustrial.com",
      phone: "+1-800-555-0199"
    },
    items,
    financials: {
      subtotal: Number(subtotal.replace(/,/g, "")),
      tax: Number(tax.replace(/,/g, "")),
      total: Number(total.replace(/,/g, ""))
    }
  }
};

return [
  {
    json: {
      orderId: "LEG-8841",
      orderDate: "10/14/2026",
      sourceTimezone: "America/New_York",
      customer: {
        rawName: " jOHn dOE-sMITH ",
        email: "JOHN.DOE@GMAIL.COM ",
        phone: "(555) 019-2834"
      },
      items: [
        {
          sku: "item-01",
          description: "Mechanical Keyboard",
          unitPrice: " $129.99 ",
          quantity: 2
        },
        {
          sku: "item-02",
          description: "Wrist Rest",
          unitPrice: "24.50",
          quantity: 1
        }
      ],
      discountPercent: 10
    }
  },
  {
    json: {
      orderId: "LEG-8842",
      orderDate: "2026-10-15T08:45:00-07:00",
      sourceTimezone: "America/Los_Angeles",
      customer: {
        rawName: "ALICE WONDERLAND",
        email: "alice@adventures.co.uk",
        phone: "+44 20 7946 0919"
      },
      items: [
        {
          sku: "item-09",
          description: "UltraWide Monitor 34-inch",
          unitPrice: "499.00 USD",
          quantity: 1
        },
        {
          sku: "item-12",
          description: "Monitor Arm Mount",
          unitPrice: "$85.00",
          quantity: 2
        }
      ],
      discountPercent: 15
    }
  }
];

const item = $input.item.json;
const rawDate = String(item.orderDate || "").trim();
const tz = item.sourceTimezone || "UTC";

let parsedDate;

if (rawDate.includes("/")) {
  parsedDate = DateTime.fromFormat(
    rawDate,
    "MM/dd/yyyy",
    { zone: tz }
  );
} else {
  parsedDate = DateTime.fromISO(
    rawDate,
    { setZone: true }
  );
}

if (!parsedDate.isValid) {
  throw new Error(
    `Invalid order date for ${item.orderId}: ${rawDate}`
  );
}

return {
  json: {
    ...item,
    normalizedDateUtc: parsedDate.toUTC().toISO(),
    displayDate: parsedDate.toFormat(
      "yyyy-MM-dd HH:mm:ss"
    )
  }
};

const item = $input.item.json;

const cleanedItems = (item.items || []).map((it) => {
  const priceText = String(it.unitPrice ?? "0")
    .replace(/,/g, "")
    .replace(/[^0-9.]/g, "");

  const unitPrice = Number(priceText);
  const quantity = Number(it.quantity);

  if (!Number.isFinite(unitPrice) || unitPrice < 0) {
    throw new Error(`Invalid unit price for ${it.sku}`);
  }

  if (!Number.isInteger(quantity) || quantity <= 0) {
    throw new Error(`Invalid quantity for ${it.sku}`);
  }

  return {
    sku: it.sku,
    description: String(it.description || "").trim(),
    unitPrice,
    quantity,
    lineTotal: Number((unitPrice * quantity).toFixed(2))
  };
});

const subtotal = Number(
  cleanedItems.reduce(
    (sum, it) => sum + it.lineTotal, 0
  ).toFixed(2)
);

const discountRate = Number(item.discountPercent || 0) / 100;

if (discountRate < 0 || discountRate > 1) {
  throw new Error("Discount must be between 0 and 100");
}

const discount = Number(
  (subtotal * discountRate).toFixed(2)
);

const discountedSubtotal = Number(
  (subtotal - discount).toFixed(2)
);

const tax = Number(
  (discountedSubtotal * 0.08).toFixed(2)
);

const total = Number(
  (discountedSubtotal + tax).toFixed(2)
);

const rawName = String(
  item.customer?.rawName || ""
).trim();

const fullName = rawName
  .toLowerCase()
  .replace(/\b\w/g, (c) => c.toUpperCase());

return {
  json: {
    sourceType: "LEGACY_JSON",
    orderId: item.orderId,
    orderDate: item.normalizedDateUtc,
    customer: {
      fullName,
      email: String(item.customer?.email || "")
        .trim()
        .toLowerCase(),
      phone: item.customer?.phone || ""
    },
    items: cleanedItems,
    financials: {
      subtotal,
      discount,
      tax,
      total
    }
  }
};

const items = $input.all();

const totalAmount = items.reduce(
  (sum, item) =>
    sum + Number(item.json.amountPayable || 0),
  0
);

return [
  {
    json: {
      batchStatus: "COMPLETED",
      totalRecordsProcessed: items.length,
      totalRevenueProcessed: Number(
        totalAmount.toFixed(2)
      ),
      summaryTimestamp: $now.toISO()
    }
  }
];
